from core import *
def mk(spans,tex=None,ol=True,fix=None):
    l=L()
    for sp in spans:
        r,c0,c1=sp[:3]; ch=sp[3] if len(sp)>3 else '#'
        for c in range(c0,c1+1): l.put(r,c,ch)
    autoshade(l,tex)
    if fix: fix(l)
    if ol: outline(l)
    return l
def sc(top=-1,wide=0,hl=2,side=True):
    """scalp: rows top..hl, widening dome; returns spans"""
    sp=[];rows=list(range(top,hl+1))
    for i,r in enumerate(rows):
        w=min(i,3)
        c0=max(4-w-wide,0) if r<1 else 2-wide; c1=14-c0
        if r>=1: c0,c1=2-wide,12+wide
        sp.append((r,c0,c1))
    return sp
def sides(r0,r1,w=2,wide=0,ch='#'):
    return [(r,2-wide,2-wide+w-1,ch) for r in range(r0,r1+1)]+[(r,12+wide-w+1,12+wide,ch) for r in range(r0,r1+1)]
def tails(r0,r1,w=3,wide=1):
    return sides(r0,r1,w,wide)
